const { describe, test, expect, beforeAll } = require('@jest/globals');

let mergeOpt;

beforeAll(() => {
  // Ensure plugins is an array to satisfy module expectations
  global.plugins = [];

  const mod = require('../../../src/options/merge.js');
  let candidate = null;

  if (typeof mod === 'function') {
    candidate = mod;
  } else if (mod && typeof mod === 'object') {
    if (typeof mod.mergeOpt === 'function') {
      candidate = mod.mergeOpt;
    } else if (typeof mod.default === 'function') {
      candidate = mod.default;
    } else {
      for (const value of Object.values(mod)) {
        if (typeof value === 'function') {
          candidate = value;
          break;
        }
      }
    }
  }

  if (typeof candidate !== 'function') {
    throw new Error('mergeOpt not found');
  }

  mergeOpt = candidate;
});

