    validateSubclass = mod.validateSubclass;
  } else if (mod && typeof mod.default === 'function') {
    validateSubclass = mod.default;
  }
} catch (e) {
  // If import fails, we'll throw a clear error during test run
  validateSubclass = null;
}

if (typeof validateSubclass !== 'function') {
  throw new Error('Unable to load validateSubclass function from src/subclass/validate.js');
}

describe('validateSubclass', () => {
  test('throws with correct message when subclass is not registered', () => {
    class CustomError extends Error {}
    const name = CustomError.name;
    const parentName = Object.getPrototypeOf(CustomError).name;

    const expected = `"new ${name}()" must not be directly called.
This error class should be created like this instead:
  export const ${name} = ${parentName}.subclass('${name}')`;

    expect(() => validateSubclass(CustomError)).toThrow(expected);
  });

  test('throws with correct message when parent is TypeError', () => {
    class CustomTypeError extends TypeError {}
    const name = CustomTypeError.name;
    const parentName = Object.getPrototypeOf(CustomTypeError).name; // Should be "TypeError"

    const expected = `"new ${name}()" must not be directly called.
This error class should be created like this instead:
  export const ${name} = ${parentName}.subclass('${name}')`;

    expect(() => validateSubclass(CustomTypeError)).toThrow(expected);
  });
});

